    q(57, "B", "現在進行形の疑問文", NARABE + "\nあなたのお兄さんは今、宿題をしていますか。（ your brother / doing / is / his homework ）now?", EN("Is your brother doing his homework now?"), "Is ＋主語＋ doing ～?", near=["Does your brother doing his homework now?"])
